// Regenerates content/tasks/index.ts from the task files on disk.
//   node scripts/register-tasks.mjs
import { readdirSync, writeFileSync } from "node:fs";

const files = readdirSync("content/tasks")
  .filter((f) => f.endsWith(".ts") && f !== "index.ts" && !f.startsWith("_") && !f.endsWith(".test.ts"))
  .sort();
const ident = (f) => f.replace(/\.ts$/, "").replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const out = [
  "/**",
  " * Registry of task files (generated by scripts/register-tasks.mjs; edit by re-running it).",
  " * The content validator fails if a file in this folder is missing from this list.",
  " */",
  ...files.map((f) => `import ${ident(f)} from "./${f.replace(/\.ts$/, "")}";`),
  "",
  "export const taskFiles: Record<string, unknown[]> = {",
  ...files.map((f) => `  "${f}": ${ident(f)},`),
  "};",
  "",
].join("\n");
writeFileSync("content/tasks/index.ts", out);
console.log(`Registered ${files.length} task files.`);
